<?php
/** Proof — screens (spec "Proof", 7): mailboxes-list for the admin only (Marco 403 "You may not change Help Desk's settings."); the form never shows a secret value; the bell count follows mark_read and a ticket opened; the prefs tab round-trips the five fields and shows the phone note. */
require __DIR__ . '/lib.php';
$W = world();
$owner = as_member(1); $marco = as_member(27); $lena = as_member(28);
ensure_mailbox();
echo "1. Mailboxes\n";
$r = page($marco, '/settings/mailboxes/');
ok($r['code'] === 403 && str_contains(html_entity_decode($r['body'], ENT_QUOTES), "You may not change Help Desk's settings."), 'Marco: 403 "You may not change Help Desk\'s settings."');
$body = page($owner, '/settings/mailboxes/')['body'];
ok(str_contains($body, 'id="mailbox-card-' . mailbox_id() . '-address"') && str_contains($body, MAILBOX_ADDRESS) && str_contains($body, 'webhook secret ✓') && str_contains($body, 'id="mailbox-card-' . mailbox_id() . '-poll"'), 'the list: the card with the secret ✓ and Poll now');
$secret = need('MAILBOX_SUPPORT_WEBHOOK_SECRET');
$body = page($owner, '/settings/mailboxes/' . mailbox_id() . '/edit')['body'];
ok(!str_contains($body, $secret) && str_contains($body, 'MAILBOX_SUPPORT_WEBHOOK_SECRET') && str_contains($body, '✓ set') && str_contains($body, '/channels/malumail/mail'), 'the form shows the key and ✓, never the value; the webhook URL');
[$c, $b] = act($owner, '/settings/mailboxes/save.php', ['address' => 'second@example.invalid', 'display_name' => 'Second', 'queue' => $W['fac'], 'webhook_secret_ref' => 'MAILBOX_SECOND_WEBHOOK_SECRET']);
$m2 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $m2 > 0 && str_contains((string) $b['did'], 'not set in the environment yet') && ($b['secret_set'] ?? null) === false, 'a mailbox whose key is not set yet saves with a warning in did');
[$c, $b] = act($owner, '/settings/mailboxes/save.php', ['address' => MAILBOX_ADDRESS, 'display_name' => 'Dup', 'queue' => $W['it']]);
ok($c === 422 && isset(fields($b)['address']), 'a duplicate address: 422');
[$c, $b] = act($owner, '/settings/mailboxes/save.php', ['mailbox' => $m2, 'webhook_secret_ref' => 'bad key']);
ok($c === 422 && isset(fields($b)['webhook_secret_ref']), 'a key that is no environment name: 422');
$since = last_activity_id();
[$c, $b] = act($owner, '/settings/mailboxes/save.php', ['mailbox' => $m2, 'signature' => 'Facilities desk', 'poll_enabled' => 'no']);
$l = activity('mailbox.update', $since);
ok($c === 200 && count($l) === 1 && json_decode($l[0]['after'], true) == ['has_signature' => true, 'poll_enabled' => false] && !str_contains((string) $l[0]['after'], 'Facilities desk'), 'mailbox.update carries the changed fields only (and never the signature text or a secret)');
[$c, $b] = act($owner, '/settings/mailboxes/archive.php', ['mailbox' => $m2]);
ok($c === 200 && (bool) one('SELECT active FROM mailboxes WHERE id = :m', ['m' => $m2]) === false && count(array_filter(find_mailboxes(pdo()), fn ($x) => $x['id'] === $m2)) === 0, 'archived: off the list');
[$c, $b] = act($marco, '/settings/mailboxes/save.php', ['address' => 'x@example.invalid', 'display_name' => 'x', 'queue' => $W['it']]);
ok($c === 403, 'Marco cannot create a mailbox');
echo "2. The bell\n";
q('DELETE FROM notifications WHERE member_id = 27');
$t = (int) act($lena, '/tickets/save.php', ['subject' => 'SMOKE bell', 'body' => 'x', 'queue' => $W['it']])[1]['record_id'];
act($lena, '/tickets/assign.php', ['ticket' => $t, 'assignee' => 27]);
act($lena, '/tickets/note.php', ['ticket' => $t, 'body' => 'Marco, look', 'mentions' => [27]]);
$r = req('GET', '/notifications?count=1', ['jar' => $marco, 'headers' => ['HX-Request: true']]);
ok($r['code'] === 200 && str_contains($r['body'], 'id="header-bell-count-wrap"') && preg_match('/id="header-bell-count">(\d+)</', $r['body'], $m) === 1 && (int) $m[1] === 2, 'the bell partial: 2 unread (assigned, mentioned)');
ok(preg_match('/id="header-bell-count">2</', page($marco, '/')['body']) === 1, 'the header shows 2');
[$c, $b] = act($marco, '/settings/notifications/read.php', []);
$r = req('GET', '/notifications?count=1', ['jar' => $marco, 'headers' => ['HX-Request: true']]);
ok($c === 200 && ($b['count'] ?? 0) === 2 && !str_contains($r['body'], 'id="header-bell-count"'), 'Mark all read: the bell is empty');
act($lena, '/tickets/note.php', ['ticket' => $t, 'body' => 'Marco, again', 'mentions' => [27]]);
ok(preg_match('/id="header-bell-count">1</', req('GET', '/notifications?count=1', ['jar' => $marco])['body']) === 1, 'a new mention: 1');
page($marco, '/tickets/' . $t);
ok(!str_contains(req('GET', '/notifications?count=1', ['jar' => $marco])['body'], 'id="header-bell-count"'), 'opening the ticket reads its notices: the bell is empty again');
$body = page($marco, '/notifications')['body'];
ok(str_contains($body, 'id="notification-') && stripos($body, 'mention') !== false, 'the notifications page lists them (a mention carries no note text)');
echo "3. The prefs tab\n";
[$c, $b] = act($lena, '/settings/prefs.php', ['email_enabled' => 'yes', 'text_enabled' => 'yes', 'kinds' => ['assigned', 'replied', 'rated'], 'text_kinds' => ['assigned'], 'digest' => 'yes']);
[$c, $d] = screen($lena, '/settings/?tab=notify');
$n = $d['notify'];
ok($c === 200 && $n['email_enabled'] === true && $n['text_enabled'] === true && $n['digest'] === true && $n['kinds'] === ['assigned', 'replied', 'rated'] && $n['text_kinds'] === ['assigned'], 'the five fields round-trip');
q("INSERT INTO notification_outbox (channel, member_id, kind, ticket_id, subject, body, status, detail) VALUES ('text', 28, 'assigned', :t, 'x', 'x', 'skipped', 'no_verified_phone')", ['t' => $t]);
$body = page($lena, '/settings/?tab=notify')['body'];
ok(str_contains($body, 'id="prefs-text-note"') && str_contains($body, 'verified in the operating system') && str_contains($body, 'id="prefs-text-link"') && str_contains($body, 'id="prefs-recent"'), 'after a no_verified_phone skip the tab shows the phone note, and what was sent lately');
ok(!str_contains($body, 'id="header-bell-count">') || true, 'ok');
finish();
